"""Verify geometry rejection/acceptance evidence generated by real Excel."""
import argparse
import hashlib
import json
from pathlib import Path


def read(p):
    return json.loads(p.read_text(encoding='utf-8-sig'))


if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    for key in ('root', 'book', 'out'):
        ap.add_argument('--' + key, type=Path, required=True)
    a = ap.parse_args()
    sha = hashlib.sha256(a.book.read_bytes()).hexdigest()
    probe = read(a.root / 'probe' / 'geometry.json')
    assert probe['status'] == 'PASS' and probe['book_sha256'].lower() == sha
    assert len(probe['cases']) == 9 and all(c['status'] == 'PASS' for c in probe['cases'])
    rejected = {'internal_inversion', 'random_internal', 'degenerate', 'near_degenerate', 'square_small'}
    cases = []
    for case in probe['cases']:
        name = case['case']
        folder = a.root / ('issue59_' + name)
        r = read(folder / ('expected_failure.json' if name in rejected else 'result.json'))
        assert r['book_sha256'].lower() == sha, name
        if name in rejected:
            assert r['status'].startswith('INPUT_ERROR|') and '要素=1' in r['status'], name
            assert r['successful_increments'] == 0 and not (folder / 'result.json').exists(), name
            if name in {'internal_inversion', 'random_internal'}:
                assert '参照領域内で負' in r['status'], name
            status = 'REJECTED_BEFORE_COMMIT'
        else:
            assert r['status'].startswith('PASS|') and r['metrics'][3] < 1e-6, name
            assert abs(r['metrics'][0] - r['metrics'][2]) < max(1e-7, abs(r['metrics'][0]) * 1e-7), name
            status = 'ACCEPTED_WITH_FORCE_BALANCE'
        cases.append({'case': name, 'status': status})
    result = {'status': 'PASS', 'book_sha256': sha, 'cases': cases,
              'scope': 'nine certificate/runtime probes and nine fresh analysis inputs; positive tiny square passes relative certificate but is rejected by the pre-existing absolute runtime Jacobian threshold'}
    a.out.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
    print('PASS: nine geometry probes and nine Excel inputs')
